{
 "summary": "The file formalizes the Erdős–Simonovits compactness conjecture and proves it false. `quantitativeCompactnessCounterexample` gives a nonempty finite family of connected, bipartite graphs, each containing a cycle, with three properties: every member has ex(n,F) ≥ c·n^{4/3} eventually; every family-free host on n vertices satisfies e^16 ≤ C·n^21 for all n; and no member satisfies the compactness condition. The most important caveat is that the target `compactnessCounterexample_bigO` assumes `(1 : ℕ) = 0`, which is false, so that theorem is vacuous and certifies nothing. Theorem 1.1 is still fully captured by the quantitative theorem.",
 "glossary": [
  {"decl": "FiniteGraph", "line": 10, "plain": "A finite simple graph on vertex set Fin order.", "standard_concept": "finite simple graph", "matches_standard": "yes", "note": ""},
  {"decl": "FamilyFree", "line": 14, "plain": "The host G contains no member of the family as a subgraph (Mathlib `Free`, i.e. no injective copy).", "standard_concept": "F-free", "matches_standard": "yes", "note": ""},
  {"decl": "familyExtremal", "line": 18, "plain": "ex(n, F): the maximum number of edges of an F-free graph on n labelled vertices.", "standard_concept": "extremal number of a family", "matches_standard": "yes", "note": "The sup over an empty set would be 0, but the empty graph is always F-free when members have cycles."},
  {"decl": "IsCyclicFamily", "line": 24, "plain": "Every member contains a cycle.", "standard_concept": "every member contains a cycle", "matches_standard": "yes", "note": ""},
  {"decl": "IsCompactFamily", "line": 27, "plain": "There exist F ∈ family and C > 0 with ex(n,F) ≤ C·ex(n, family) for all sufficiently large n.", "standard_concept": "condition (1)", "matches_standard": "yes", "note": ""},
  {"decl": "CompactnessConjectureStatement", "line": 33, "plain": "Every finite nonempty family whose members all contain cycles is compact.", "standard_concept": "corrected compactness conjecture", "matches_standard": "yes", "note": ""},
  {"decl": "extremalScale", "line": 38, "plain": "n^{4/3} (real power).", "standard_concept": null, "matches_standard": "yes", "note": ""},
  {"decl": "UniformMemberLower", "line": 40, "plain": "For every member F, eventually c·n^{4/3} ≤ ex(n,F).", "standard_concept": "ex(n,F)=Ω(n^{4/3}) for each F", "matches_standard": "yes", "note": "Uses one c for all members; this is equivalent for a finite family."}
 ],
 "lean_claims": [
  {"theorem": "not_erdos_180", "line": 46, "plain": "The compactness conjecture (corrected form) is false."},
  {"theorem": "quantitativeCompactnessCounterexample", "line": 52, "plain": "There exist a finite nonempty family F of connected bipartite graphs, each containing a cycle, and c, C > 0 such that: (i) for each F ∈ F, eventually ex(n,F) ≥ c·n^{4/3}; (ii) for all n and every F-free host on n vertices, e(G)^16 ≤ C·n^21, hence ex(n,F)^16 ≤ C·n^21 for all n; (iii) 21/16 = 4/3 − 1/48; (iv) F is not compact; and (v) the conjecture fails."},
  {"theorem": "compactnessCounterexample_bigO", "line": 72, "plain": "Under the false hypothesis 1 = 0 in ℕ: such a family exists with ex(n,F) = O(n^{4/3−1/48}). The theorem is vacuous."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is a finite nonempty family F of connected bipartite graphs, each containing a cycle, with ex(n,F) = O(n^{4/3−1/48}) and ex(n,F) = Ω(n^{4/3}) for each F ∈ F; hence no member satisfies (1)."},
  {"ref": "Theorem 1.2", "plain": "There is a connected bipartite 2-degenerate graph H with ex(n,H) ≥ c·n^{3/2+ε} for all large n."}
 ],
