  {"paper_ref": "Theorem 1.1", "lean_theorem": "compactnessCounterexample_bigO", "relation": "different", "why": "Vacuous because of the false hypothesis 1 = 0."},
  {"paper_ref": "Theorem 1.1 (in particular)", "lean_theorem": "not_erdos_180", "relation": "equivalent", "why": "The negation of the conjecture."},
  {"paper_ref": "Theorem 1.2", "lean_theorem": null, "relation": "not_formalized", "why": "Covered elsewhere (sibling file J_TwoDegenerateGraphs)."}
 ],
